Customer Portal.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Customer Portal container

Container_Boundary(customer_portal, "Customer Portal") {
    Component(Claim_Submission_UI, "Claim Submission UI", "React & MSAL.js", "Powers UI components for policyholders and brokers to submit and track claims.")
    Component(Authentication_Manager, "Authentication Manager", "MSAL.js / OIDC / OAuth2", "Handles user authentication with Microsoft Entra ID.")
}

Rel(Claim_Submission_UI, Authentication_Manager, "Authenticates users via", "OIDC/OAuth2")

@enduml

PostgreSQL Read-Cache.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the PostgreSQL Read-Cache container

Container_Boundary("PostgreSQL Read-Cache", "PostgreSQL Read-Cache") {
    Component("CacheStorageEngine", "Cache Storage Engine", "Azure Database for PostgreSQL Flexible Server", "Managed database instance that caches mainframe data for modern adjusters to ensure sub-2-second response times.")
    Component("SyncConsumerComponent", "Sync Consumer Component", ".NET worker hosted in Azure Container Apps", "Ingests delta change events from the messaging broker and writes updates to the cache storage engine via connection pooling.")
    Component("AuditVersioningManager", "Audit & Versioning Manager", ".NET Library / Service Layer", "Manages audit trails and versioning for data synchronization and compliance.")
}

Rel(SyncConsumerComponent, CacheStorageEngine, "Writes updates via connection pooling", "TCP / TLS 1.3")
Rel(CacheStorageEngine, AuditVersioningManager, "Invokes audit and versioning checks for data modifications", "")

@enduml

Claims Processing Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(claims_processing_service, "Claims Processing Service") {
    Component(Claim Orchestrator Component, "Claim Orchestrator Component", ".NET Core", "Orchestrates claim processing workflows and coordinates business transactions.")
    Component(Claim Domain Model Component, "Claim Domain Model Component", ".NET Core", "Encapsulates the core business logic and domain rules for claims.")
    Component(Exception Handler Component, "Exception Handler Component", ".NET Core", "Handles exceptions, failures, and manages dead-letter routing.")
    Component(Integration Client Component, "Integration Client Component", ".NET Core with Polly", "Manages communication with external systems and the Anti-Corruption Layer.")
}

Rel(Claim Orchestrator Component, Claim Domain Model Component, "Executes business logic")
Rel(Claim Orchestrator Component, Exception Handler Component, "Delegates error handling")
Rel(Claim Orchestrator Component, Integration Client Component, "Dispatches external calls and messaging")

@enduml

Anti-Corruption Layer (ACL).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("AntiCorruptionLayer", "Anti-Corruption Layer (ACL)") {
    Component(ServiceBusMessageListener, "Service Bus Message Listener", ".NET Core / Azure Service Bus SDK", "Listens for claim migration and processing events from the Azure Service Bus.")
    Component(JsonToCobolMapper, "JSON-to-COBOL Mapper", ".NET Core Library", "Translates modern JSON payloads into mainframe-compatible COBOL structures.")
    Component(ReplayCoordinator, "Replay Coordinator", ".NET Core API Controller", "Manages claim replays and coordinates with the Migration Operations Dashboard via REST over HTTPS with Entra ID JWT validation.")
    Component(GrpcMainframeClient, "gRPC Mainframe Client", "gRPC / .NET Core", "Communicates securely with the Legacy Mainframe using gRPC over mTLS, utilizing secrets from Azure Key Vault.")
}

Rel(ServiceBusMessageListener, JsonToCobolMapper, "Forwards incoming messages for translation")
Rel(JsonToCobolMapper, GrpcMainframeClient, "Passes mapped COBOL data for legacy processing")
Rel(ReplayCoordinator, JsonToCobolMapper, "Triggers data mapping for claim replays")
@enduml
